CREATE TABLE IF NOT EXISTS users (name VARCHAR(64) PRIMARY KEY,password VARCHAR(128) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_login DATETIME NULL,last_logout DATETIME NULL);
CREATE TABLE IF NOT EXISTS audit (id BIGINT AUTO_INCREMENT PRIMARY KEY,at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,event TEXT);
CREATE TABLE IF NOT EXISTS sessions (id VARCHAR(36) PRIMARY KEY,username VARCHAR(64),remote_ip VARCHAR(128),protocol VARCHAR(16),connected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,disconnected_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS files (path VARCHAR(512) PRIMARY KEY,owner VARCHAR(64),size BIGINT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
